DROP VIEW IF EXISTS `view_periods`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_periods` AS WITH wet_streaks AS ( SELECT `date`, `sum_rainfall`, (`date` - INTERVAL ROW_NUMBER() OVER (ORDER BY `date`) DAY) AS `streak_id` FROM `aggregated` WHERE `sum_rainfall` > 0 ), dry_streaks AS ( SELECT `date`, `sum_rainfall`, (`date` - INTERVAL ROW_NUMBER() OVER (ORDER BY `date`) DAY) AS `streak_id` FROM `aggregated` WHERE `sum_rainfall` = 0 ) ( SELECT 'longest_wet_period' AS `type`, MIN(`date`) AS `start_date`, MAX(`date`) AS `end_date`, COUNT(1) AS `consecutive_days`, SUM(`sum_rainfall`) AS `total_rain_amount` FROM wet_streaks GROUP BY `streak_id` ORDER BY `consecutive_days` DESC LIMIT 1 ) UNION ALL ( SELECT 'longest_dry_period' AS `type`, MIN(`date`) AS `start_date`, MAX(`date`) AS `end_date`, COUNT(1) AS `consecutive_days`, SUM(`sum_rainfall`) AS `total_rain_amount` FROM dry_streaks GROUP BY `streak_id` ORDER BY `consecutive_days` DESC LIMIT 1 );